  $sources=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'})
  foreach($file in $sources){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Original QK capture changed'}}
  $spec.input_files=$sources;$spec.arguments=@('--q7169',$q,$k)
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured q7169 layer3 QK'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146';$spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
 }
 if($Kind -eq 'real'){
  $inputTensor='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin';$weightTensor='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin';$referenceTensor='D:\projects\sm121-qkv-reference-9510d980.bin'
  $tensors=@(@{path=$inputTensor;sha256='6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161'},@{path=$weightTensor;sha256='b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f'},@{path=$referenceTensor;sha256='9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37'})
  foreach($tensor in $tensors){if((Get-FileHash $tensor.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tensor.sha256){throw 'Original QKV tensor changed'}}
  $spec.arguments=@('--real-qkv',$inputTensor,$weightTensor,$referenceTensor,'1000');$spec.tensor_inputs=$tensors
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured layer-zero QKV';$spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.gb10_reference_host='aitopatom-66c4';$spec.gb10_capture_sha256='5522ec3e4725adf459e505dff61aa3981a08b416b7b2bfe40e929ccf250b4d8b';$spec.prompt_sha256='26515be92b5563d921bade3ed6673ffe9e0c6560fbd7d78f587a0400da802804';$spec.reference_is_compute_input=$false;$spec.selector_error_bound_ppb=1000
 }
}
$out=Join-Path $repo ('build\matrix-consumer-'+$Kind+'-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(1200,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native component action failed'}
if($Action -eq 'build'){
 if($Kind -ne 'real'){
  $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
  [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
 }
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($Kind -eq 'real'){$reports=@($reports|Where-Object {$_.type -eq 'f32_carry_projection_real_replay'})}
 $count=if($Action -eq 'capture'){6}else{96}
 if($reports.Count -ne $count){throw 'Incomplete component cases'}
 foreach($report in $reports){
  if($report.raw_bit_mismatches -ne 0 -or -not $report.redzones_pass -or -not $report.immutable_inputs){throw 'Raw numerical or memory failure'}
  if($Kind -eq 'core' -and ($report.group_mismatches -ne 0 -or $report.ordered_groups -ne 2097152)){throw 'K16 trace failure'}
  if($Kind -eq 'real' -and ($report.unrounded_candidate_bit_mismatches -ne 0 -or $report.bf16_mismatches -ne 0 -or $report.elements -ne 58728448)){throw 'Original QKV mismatch'}
 }
